extends RefCounted


func run():
	var current_health: int = 25
	var amount: int = 40
	var new_health := maxi(0, current_health - amount)
	return new_health

extends RefCounted


func run():
	var target := Vector2(100, 100)
	var global_pos := Vector2(100, 100)
	var dir := (target - global_pos).normalized()
	if dir == Vector2.ZERO:
		dir = Vector2.RIGHT
	return dir

extends RefCounted


func run():
	var position := Vector2(10, 20)
	var direction := Vector2(0, 1)
	var speed := 250.0
	var delta := 0.02
	position += direction * speed * delta
	return position
